import java.util.HashMap;
import java.util.Map;

public class FibonacciDemo {
    // Naive: O(2^n) time, recomputes subproblems
    public static int fibNaive(int n) {
        if (n <= 1) return n;
        return fibNaive(n - 1) + fibNaive(n - 2);   // exponential branching
    }

    // Memoized: O(n) time, O(n) space
    public static int fibMemo(int n, Map<Integer, Integer> cache) {
        if (n <= 1) return n;
        if (cache.containsKey(n)) return cache.get(n);   // cache hit
        int result = fibMemo(n - 1, cache) + fibMemo(n - 2, cache);
        cache.put(n, result);                            // store for reuse
        return result;
    }

    public static void main(String[] args) {
        System.out.println(fibMemo(40, new HashMap<>()));  // instant: 102334155
    }
}

// Dry run fib(5): fib(4)+fib(3); fib(4) reuses cached fib(3) and fib(2)
// -> 5 unique computations instead of 15 calls.
