import java.util.ArrayList;
import java.util.List;

public class PermutationGenerator {
    public static List<String> permute(String str) {
        List<String> result = new ArrayList<>();
        backtrack(str.toCharArray(), new StringBuilder(),
                  new boolean[str.length()], result);
        return result;
    }

    private static void backtrack(char[] chars, StringBuilder current,
                                  boolean[] used, List<String> result) {
        if (current.length() == chars.length) {   // base case: full permutation
            result.add(current.toString());
            return;
        }
        for (int i = 0; i < chars.length; i++) {
            if (used[i]) continue;                 // skip used characters
            used[i] = true; current.append(chars[i]);          // choose
            backtrack(chars, current, used, result);           // explore
            current.deleteCharAt(current.length() - 1); used[i] = false; // un-choose
        }
    }
}

// permute("AB") -> [AB, BA]  (2! = 2 permutations)
