// O(1) space, no stack risk — preferred in production
public static long factorialIterative(int n) {
    long result = 1;
    for (int i = 2; i <= n; i++) {
        result *= i;                    // single accumulator
    }
    return result;
}

// factorialIterative(5): 1*2=2, *3=6, *4=24, *5=120
